package com.example.ayni.community.model;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="community_members") public class CommunityMember { @Id private UUID id; @Column(name="community_id") private UUID communityId; @Column(name="user_id") private UUID userId; @Enumerated(EnumType.STRING) private Role role; @Enumerated(EnumType.STRING) private Status status; @Column(name="joined_at") private Instant joinedAt; protected CommunityMember(){} public CommunityMember(UUID communityId,UUID userId,Role role,Status status){id=UUID.randomUUID();this.communityId=communityId;this.userId=userId;this.role=role;this.status=status;}@PrePersist void joined(){joinedAt=Instant.now();}public UUID getUserId(){return userId;}public Role getRole(){return role;}public Status getStatus(){return status;}public void approve(){status=Status.ACTIVE;}public enum Role {ADMIN,MEMBER} public enum Status {PENDING,ACTIVE,REJECTED,BANNED}}
